 */
public void initOrder(org.mybatis.jpetstore.domain.Account account, org.mybatis.jpetstore.domain.Cart cart) {
    username = account.getUsername();
    orderDate = new java.util.Date();
    shipToFirstName = account.getFirstName();
    shipToLastName = account.getLastName();
    shipAddress1 = account.getAddress1();
    shipAddress2 = account.getAddress2();
    shipCity = account.getCity();
    shipState = account.getState();
    shipZip = account.getZip();
    shipCountry = account.getCountry();
    billToFirstName = account.getFirstName();
    billToLastName = account.getLastName();
    billAddress1 = account.getAddress1();
    billAddress2 = account.getAddress2();
    billCity = account.getCity();
    billState = account.getState();
    billZip = account.getZip();
    billCountry = account.getCountry();
    totalPrice = cart.getSubTotal();
    creditCard = "999 9999 9999 9999";
    expiryDate = "12/03";
    cardType = "Visa";
    courier = "UPS";
    locale = "CA";
    status = "P";
    java.util.Iterator<org.mybatis.jpetstore.domain.CartItem> i = cart.getAllCartItems();
    while (i.hasNext()) {
        org.mybatis.jpetstore.domain.CartItem cartItem = i.next();
        addLineItem(cartItem);
    } 
}

